# ============================================================
# B. CLASSIFICATION-WINDOW SENSITIVITY (lateral-move window, gov-ended window)
#    Reruns 43's pipeline logic with alternative windows.
# ============================================================
cat("=== B. Classification-window sensitivity ===\n")

app <- read_csv(file.path(IFG_DIR, "appointment.csv"), show_col_types = FALSE)
ev  <- read_csv(file.path(IFG_DIR, "event.csv"), show_col_types = FALSE)

daily_all <- app |> filter(!is.na(end_date)) |> count(end_date, name = "n_ending_that_day")
gov_events <- ev |> filter(type %in% c("General election", "Change of prime minister")) |> pull(date)
find_handover_dates <- function(e) {
  w <- daily_all |> filter(end_date >= e - 45, end_date <= e + 45, n_ending_that_day >= 20)
  w$end_date
}
gov_end_dates <- as.Date(sort(unique(do.call(c, lapply(gov_events, find_handover_dates)))), origin = "1970-01-01")

classify <- function(lateral_window, gov_window, cluster_thr = 5) {
  starts <- app |> select(person_id, start_date)
  departures <- app |> filter(!is.na(end_date)) |>
    rowwise() |>
    mutate(moved_within_window = any(starts$person_id == person_id &
                                        starts$start_date >= end_date &
                                        starts$start_date <= end_date + lateral_window)) |>
    ungroup()
  left_govt <- departures |> filter(!moved_within_window) |>
    rowwise() |>
    mutate(gov_ended = any(abs(as.numeric(end_date - gov_end_dates)) <= gov_window)) |>
    ungroup()
  personal_window <- left_govt |> filter(!gov_ended) |> left_join(daily_all, by = "end_date") |>
    mutate(standalone = n_ending_that_day < cluster_thr,
           year = as.integer(format(end_date, "%Y"))) |>
    filter(year >= 1979, year <= 2025)

  annual <- personal_window |>
    group_by(year) |>
    summarise(n_total = n(), n_standalone = sum(standalone), .groups = "drop") |>
    complete(year = 1979:2025, fill = list(n_total = 0, n_standalone = 0))

  n_active <- sapply(annual$year, function(yr) {
    dd <- as.Date(sprintf("%d-07-01", yr))
    app |> filter(start_date <= dd, is.na(end_date) | end_date >= dd) |> nrow()
  })
  annual$n_active <- n_active
  annual$standalone_rate <- 100 * annual$n_standalone / annual$n_active

  annual |>
    mutate(period = cut(year, breaks = c(1978, 1988, 1997, 2009, 2019, 2025),
                         labels = c("1979-88", "1989-97", "1998-2009", "2010-19", "2020-25"))) |>
    group_by(period) |>
    summarise(mean_standalone_rate = mean(standalone_rate), .groups = "drop") |>
    mutate(n_standalone_total = sum(annual$n_standalone))
}

specs <- tribble(
  ~label,                                ~lateral, ~gov,
  "Baseline (14d lateral, +-3d gov)",     14,       3,
  "Tighter lateral window (7d)",          7,        3,
  "Looser lateral window (30d)",          30,       3,
  "Looser gov-ended window (+-7d)",       14,       7
)

window_results <- lapply(seq_len(nrow(specs)), function(i) {
  r <- classify(specs$lateral[i], specs$gov[i])
  r |> mutate(spec = specs$label[i]) |> select(spec, period, mean_standalone_rate, n_standalone_total)
}) |> bind_rows()

window_wide <- window_results |>
  select(spec, period, mean_standalone_rate) |>
  pivot_wider(names_from = period, values_from = mean_standalone_rate)

