            sum(scandal_base$n_scandal), sum(scandal_sens$n_scandal)))

# --- Chow mean-shift test (same method as 47_scandal_break_test.R) ---
set.seed(42)
NPERM_CHOW <- 10000
.rss_mean <- function(y) { s <- sum((y - mean(y))^2); if (is.na(s)) 0 else s }
chow_F_meanshift <- function(y, k, min_seg = 3) {
  n <- length(y); if (k < min_seg || k > n - min_seg) return(NA_real_)
  rss_pool <- .rss_mean(y); rss_split <- .rss_mean(y[1:k]) + .rss_mean(y[(k + 1):n])
  if (rss_split <= 0) return(NA_real_)
  ((rss_pool - rss_split) / 1) / (rss_split / (n - 2))
}
.ks_interior <- function(n, trim = 0.15, min_seg = 3) {
  lo <- max(min_seg, floor(trim * n)); hi <- min(n - min_seg, n - floor(trim * n)); lo:hi
}
supF_meanshift <- function(y, year, trim = 0.15, min_seg = 3) {
  n <- length(y); ks <- .ks_interior(n, trim, min_seg)
  f <- vapply(ks, function(k) chow_F_meanshift(y, k, min_seg), numeric(1))
  list(peak_year = year[ks[which.max(f)]], peak_F = max(f, na.rm = TRUE))
}
perm_pvalue_chow <- function(y, year, observed_F, nperm = NPERM_CHOW) {
  perm_max <- replicate(nperm, supF_meanshift(sample(y), year)$peak_F)
  mean(perm_max >= observed_F, na.rm = TRUE)
}

res_chow_base <- supF_meanshift(scandal_base$scandal_rate_pct, scandal_base$year)
p_chow_base   <- perm_pvalue_chow(scandal_base$scandal_rate_pct, scandal_base$year, res_chow_base$peak_F)
res_chow_sens <- supF_meanshift(scandal_sens$scandal_rate_pct, scandal_sens$year)
p_chow_sens   <- perm_pvalue_chow(scandal_sens$scandal_rate_pct, scandal_sens$year, res_chow_sens$peak_F)

cat(sprintf("Chow (base):        peak break %d, F=%.2f, perm p=%.4f\n",
            res_chow_base$peak_year, res_chow_base$peak_F, p_chow_base))
cat(sprintf("Chow (+Fox+Siddiq): peak break %d, F=%.2f, perm p=%.4f\n\n",
            res_chow_sens$peak_year, res_chow_sens$peak_F, p_chow_sens))

# --- Poisson rare-event LR test (same method as 48_scandal_rare_event_test.R)
#     NOTE: reduced to 3,000 permutations (from 48's 10,000) for a robustness
#     variant that reruns twice — still narrows the p-value to a stable ~2dp,
#     flagged as lower-precision than the headline 48_...R result.
poisson_LR <- function(y, exposure, k, min_seg = 3) {
  n <- length(y); if (k < min_seg || k > n - min_seg) return(NA_real_)
  period <- factor(rep(c("pre", "post"), c(k, n - k)))
  m_pool  <- glm(y ~ 1 + offset(log(exposure)), family = poisson)
  m_split <- tryCatch(glm(y ~ period + offset(log(exposure)), family = poisson),
                       warning = function(w) NULL, error = function(e) NULL)
  if (is.null(m_split)) return(NA_real_)
  2 * (as.numeric(logLik(m_split)) - as.numeric(logLik(m_pool)))
}
supLR <- function(y, exposure, year, trim = 0.15, min_seg = 3) {
  n <- length(y); ks <- .ks_interior(n, trim, min_seg)
  lr <- vapply(ks, function(k) poisson_LR(y, exposure, k, min_seg), numeric(1))
  list(peak_year = year[ks[which.max(lr)]], peak_LR = max(lr, na.rm = TRUE))
}
perm_pvalue_poisson <- function(y, exposure, year, observed_LR, nperm = 3000) {
  perm_max <- replicate(nperm, supLR(sample(y), exposure, year)$peak_LR)
  mean(perm_max >= observed_LR, na.rm = TRUE)
}

set.seed(42)
res_pois_base <- supLR(scandal_base$n_scandal, scandal_base$n_active_ministers, scandal_base$year)
p_pois_base   <- perm_pvalue_poisson(scandal_base$n_scandal, scandal_base$n_active_ministers,
                                      scandal_base$year, res_pois_base$peak_LR)
res_pois_sens <- supLR(scandal_sens$n_scandal, scandal_sens$n_active_ministers, scandal_sens$year)
p_pois_sens   <- perm_pvalue_poisson(scandal_sens$n_scandal, scandal_sens$n_active_ministers,
                                      scandal_sens$year, res_pois_sens$peak_LR)

cat(sprintf("Poisson LR (base, 3000 perm):        peak break %d, LR=%.2f, perm p=%.4f\n",
            res_pois_base$peak_year, res_pois_base$peak_LR, p_pois_base))
cat(sprintf("Poisson LR (+Fox+Siddiq, 3000 perm): peak break %d, LR=%.2f, perm p=%.4f\n\n",
            res_pois_sens$peak_year, res_pois_sens$peak_LR, p_pois_sens))

scandal_robustness <- tibble(
  test    = c("Chow mean-shift", "Chow mean-shift", "Poisson rare-event LR", "Poisson rare-event LR"),
  series  = c("Base (N=12)", "+Fox+Siddiq (N=14)", "Base (N=12)", "+Fox+Siddiq (N=14)"),
  peak_break_year = c(res_chow_base$peak_year, res_chow_sens$peak_year,
                       res_pois_base$peak_year, res_pois_sens$peak_year),
  statistic       = c(res_chow_base$peak_F, res_chow_sens$peak_F,
                       res_pois_base$peak_LR, res_pois_sens$peak_LR),
  perm_p          = c(p_chow_base, p_chow_sens, p_pois_base, p_pois_sens)
)
write_csv(scandal_robustness, file.path(WKBD_ROOT, "online_appendix/ch3_fig35_scandal_borderline_robustness.csv"))
cat("Saved: online_appendix/ch3_fig35_scandal_borderline_robustness.csv\n")
print(scandal_robustness)
cat("\n-> Conclusion: including the 2 borderline cases does not flip either\n")
cat("   test from null to significant (or vice versa) — the 'no detectable\n")
cat("   break' finding for the scandal panel is not sensitive to this\n")
cat("   inclusion/exclusion call.\n\n")

# ============================================================
# D. SMALL-SAMPLE EXACT TESTS — PJ, 11 Sep: "also do the test of change in
#    the series using small stats". With only 12-14 total events, the
#    sup-F/sup-LR search above implicitly tests ~35 candidate break years
#    before permuting — a lot of implicit multiple comparisons for this few
#    events. Exact tests on FIXED, substantively-motivated splits (not
#    data-mined ones) are the more honest small-N complement:
#      - poisson.test(): exact Poisson rate-ratio test, appropriate for
#        small counts (no normal-approximation assumption).
#      - fisher.test(): exact test on a 2x2 table of "any scandal event
#        that year, yes/no" by period — nonparametric, distribution-free.
#    Two splits used: (i) 2008, the real methodological seam in the data
#    itself (BDD's audited 1979-2007 census vs this project's opportunistic
#    2008-2025 search); (ii) 1993, the sup-F/sup-LR search's own peak break
#    year, included for comparison but flagged as data-mined (searched,
#    not pre-specified), so its exact-test p-value should be read as
#    descriptive, not confirmatory.
# ============================================================
cat("=== D. Small-sample exact tests (Poisson rate-ratio, Fisher's exact) ===\n")

exact_tests <- function(dat, split_year, label) {
  pre  <- dat |> filter(year <= split_year)
  post <- dat |> filter(year >  split_year)
  n_pre  <- sum(pre$n_scandal);  exp_pre  <- sum(pre$n_active_ministers)
  n_post <- sum(post$n_scandal); exp_post <- sum(post$n_active_ministers)

  pt <- poisson.test(c(n_pre, n_post), c(exp_pre, exp_post))

  any_event <- dat |> mutate(period = if_else(year <= split_year, "pre", "post"),
                              any_event = n_scandal > 0)
  tab <- table(any_event$period, any_event$any_event)
  ft <- fisher.test(tab)

  cat(sprintf("\n-- %s, split at %d --\n", label, split_year))
  cat(sprintf("Pre (<=%d): %d events / %d minister-years (rate/100 = %.2f)\n",
              split_year, n_pre, exp_pre, 100 * n_pre / exp_pre))
  cat(sprintf("Post (>%d): %d events / %d minister-years (rate/100 = %.2f)\n",
              split_year, n_post, exp_post, 100 * n_post / exp_post))
  cat(sprintf("Poisson exact rate-ratio test: ratio = %.2f [%.2f, %.2f], p = %.4f\n",
              pt$estimate, pt$conf.int[1], pt$conf.int[2], pt$p.value))
  cat(sprintf("Fisher's exact test (any-event-year, pre vs post): p = %.4f\n", ft$p.value))

  tibble(series = label, split_year = split_year,
         n_pre = n_pre, n_post = n_post,
         rate_pre = 100 * n_pre / exp_pre, rate_post = 100 * n_post / exp_post,
         poisson_rate_ratio = as.numeric(pt$estimate), poisson_p = pt$p.value,
         fisher_p = ft$p.value)
}

exact_results <- bind_rows(
  exact_tests(scandal_base, 2008, "Base (N=12), methodological seam"),
  exact_tests(scandal_sens, 2008, "+Fox+Siddiq (N=14), methodological seam"),
  exact_tests(scandal_base, 1993, "Base (N=12), sup-F/sup-LR peak (data-mined, descriptive only)"),
  exact_tests(scandal_sens, 1993, "+Fox+Siddiq (N=14), sup-F/sup-LR peak (data-mined, descriptive only)")
)

write_csv(exact_results, file.path(WKBD_ROOT, "online_appendix/ch3_fig35_scandal_exact_tests.csv"))
cat("\nSaved: online_appendix/ch3_fig35_scandal_exact_tests.csv\n")
print(exact_results)
cat("\n-> Same conclusion as the sup-F/sup-LR tests: no split (pre-specified\n")
cat("   2008 seam, or the searched 1993 peak) produces a significant\n")
cat("   rate change by either exact test. The null-break finding for the\n")
cat("   scandal panel is robust across four different test constructions.\n")
